// Assistant library access: domain manifest + lazy pack loading + search.
// The packs are generated by tools/gen-docs-assistants.mjs and loaded on
// demand (one small chunk per domain); nothing imports the packs statically.
// The core pack (harvested chayuan-wps builtin helpers) is a static module —
// it merges in here as the pinned first domain「常用助手」without touching the
// generated manifest, so regeneration never disturbs it.
import { DOC_ASSISTANT_DOMAINS, DOC_ASSISTANT_TOTAL, loadAllDomains, loadDomain } from './packs/manifest'
import type { AssistantDomainInfo } from './packs/manifest'
import { CORE_ASSISTANTS } from './core-builtin'
import type { DocAssistant } from './types'

export { DOC_ASSISTANT_DOMAINS, DOC_ASSISTANT_TOTAL } from './packs/manifest'
export type { AssistantDomainInfo } from './packs/manifest'
export type { DocAssistant } from './types'
export { CORE_ASSISTANTS } from './core-builtin'
export { buildAssistantInstruction, resolveInputScope } from './build-instruction'

/** the pinned first domain the core helpers group under */
export const CORE_DOMAIN: AssistantDomainInfo = {
  key: 'core',
  label: '常用助手',
  count: CORE_ASSISTANTS.length,
}

/** full browse order: 常用助手 first, then the generated domain manifest */
export const ALL_ASSISTANT_DOMAINS: readonly AssistantDomainInfo[] = [
  CORE_DOMAIN,
  ...DOC_ASSISTANT_DOMAINS,
]

/** library size including the core pack */
export const ALL_ASSISTANTS_TOTAL = DOC_ASSISTANT_TOTAL + CORE_ASSISTANTS.length

const allCache: { promise?: Promise<Map<string, DocAssistant[]>> } = {}

/** Load every domain pack (≈4.6k assistants) plus the core pack; cached module-wide. */
export function loadAllAssistants(): Promise<Map<string, DocAssistant[]>> {
  allCache.promise ??= loadAllDomains().then((m) => {
    m.set('core', CORE_ASSISTANTS)
    return m
  })
  return allCache.promise
}

/** True once a previous loadAllAssistants() resolved. */
export function allAssistantsLoaded(): boolean {
  return allCache.promise !== undefined
}

export async function getDomainAssistants(key: string): Promise<DocAssistant[]> {
  if (key === 'core') return CORE_ASSISTANTS
  return loadDomain(key)
}

/** Flatten a domain map preserving the merged manifest order (core first) */
export function flattenByManifest(byDomain: Map<string, DocAssistant[]>): DocAssistant[] {
  const out: DocAssistant[] = []
  for (const d of ALL_ASSISTANT_DOMAINS) {
    const list = byDomain.get(d.key)
    if (list) out.push(...list)
  }
  return out
}

/** Look up a core-pack assistant by id (static, no await) */
export function findCoreAssistant(id: string): DocAssistant | undefined {
  return CORE_ASSISTANTS.find((a) => a.id === id)
}

/** AND-match space-separated terms against the searchable text of an assistant */
export function matchAssistant(doc: DocAssistant, domainLabel: string, query: string): boolean {
  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean)
  if (terms.length === 0) return true
  const haystack = [doc.label, doc.shortLabel, doc.description, domainLabel, ...doc.tags]
    .join('\n')
    .toLowerCase()
  return terms.every((t) => haystack.includes(t))
}

/** Look up assistants by id across the (already loaded) library */
export function findById(all: Iterable<DocAssistant>, id: string): DocAssistant | undefined {
  for (const doc of all) if (doc.id === id) return doc
  return undefined
}
